"""Replay production JapaneseGlide control flow with deterministic Android/native fakes.
These are host tests, not Android or SwiftKey-engine tests.
"""
from pathlib import Path
import argparse, subprocess, sys
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);p.add_argument('--tools',type=Path);p.add_argument('--work',type=Path,default=Path('/tmp/swiftkey-glide-runtime-tests'))
a=p.parse_args();root=a.root.resolve();work=a.work.resolve();host=work/'host_stubs';classes=work/'classes';classes.mkdir(parents=True,exist_ok=True)
