for source in sorted((root/'stubs').rglob('*.java')):
 name=source.relative_to(root/'stubs').as_posix()
 if name not in stubs:stubs[name]=source.read_text()
for name,text in stubs.items():
 target=host/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text+'\n')
command=['java','com.sun.tools.javac.Main','--release','8','-encoding','UTF-8','-g:none','-d',str(classes)]+[str(x) for x in sorted(host.rglob('*.java'))]+[str(root/'src/hiro/swiftkey/JapaneseGlide.java'),str(root/'tests/JapaneseGlideRuntimeTest.java')]
subprocess.run(command,check=True)
subprocess.run(['java','-cp',str(classes),'JapaneseGlideRuntimeTest'],check=True)
